Terraform modules package reusable infrastructure components.

**Create a module** (`modules/vpc/main.tf`):
```hcl
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "environment" {
  type = string
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  tags = {
    Name        = "${var.environment}-vpc"
    Environment = var.environment
  }
}

resource "aws_subnet" "public" {
  vpc_id     = aws_vpc.main.id
  cidr_block = cidrsubnet(var.vpc_cidr, 8, 1)
  tags = {
    Name = "${var.environment}-public"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_id" {
  value = aws_subnet.public.id
}
```

**Use the module** (`environments/prod/main.tf`):
```hcl
module "vpc" {
  source      = "../../modules/vpc"
  vpc_cidr    = "10.1.0.0/16"
  environment = "production"
}

module "vpc_staging" {
  source      = "../../modules/vpc"
  vpc_cidr    = "10.2.0.0/16"
  environment = "staging"
}

# Reference module outputs
resource "aws_instance" "web" {
  subnet_id = module.vpc.public_subnet_id
  # ...
}
```

**Public modules**: use the Terraform Registry (registry.terraform.io) for community modules.
